# поток: mkt / WB read-only audit
"""Offline review of WB inventory and proposed bid trials, behind existing BI authentication."""
import collections
import csv
import datetime as dt
from decimal import Decimal as D
import html
import json
from pathlib import Path
from zoneinfo import ZoneInfo

P = Path(__file__).parent
load = lambda file: json.loads(file.read_text())
readcsv = lambda file: list(csv.DictReader(file.open(encoding='utf-8-sig')))
s = load(P / 'summary.json')
coverage = load(P / 'ad_coverage.json')
inventory = readcsv(P / 'inventory_all_nontrash.csv')
plans = readcsv(P / 'bid_candidates.csv')
floor = readcsv(P / 'already_at_floor.csv')
campaigns = []
for file in P.glob('fullstats_batch_*.json'):
    campaigns += load(file)['response']
spend = sum((D(str(c['sum'])) for c in campaigns), D(0))
revenue = sum((D(str(c['sum_price'])) for c in campaigns), D(0))
ad_orders = sum(int(c['orders']) for c in campaigns)
billing = load(P / 'raw/actual_expense_history.json')
charges = sum((D(str(x['updSum'])) for x in billing['response']), D(0)) if billing['http'] == 200 else None
labels = {'bundles': 'Бандлы', 'children': 'Дочерние', 'new_6months': 'Новинки за полгода', 'old': 'Старые'}


def money(x):
    return f'{D(str(x)):,.2f}'.replace(',', ' ')


def table(head, rows):
    return '<div class="scroll"><table><tr>' + ''.join('<th>' + html.escape(str(x)) + '</th>' for x in head) + '</tr>' + ''.join(
        '<tr>' + ''.join('<td>' + html.escape(str(x)) + '</td>' for x in row) + '</tr>' for row in rows) + '</table></div>'


in_stock = [r for r in inventory if r['availability'] == 'IN_STOCK']
group_rows = []
for key, label in labels.items():
    rows = [r for r in in_stock if r['segment'] == key]
    group_rows.append([label, len(rows), sum(r['in_running_ad'] == 'True' for r in rows),
                       sum(r['only_paused_or_ready_ad'] == 'True' for r in rows),
                       sum(r['in_any_unfinished_campaign'] == 'False' for r in rows)])
group_rows.append(['ИТОГО', len(in_stock), s['in_stock_running_ads'], s['in_stock_paused_only'], s['in_stock_no_unfinished_campaign']])
body = '<h1>WB акк1: реклама и товары вне неё</h1><p><b>Обновление 09.11, 22:58 МСК:</b> по уточнённой команде пополнена 21 РК с остатком ≤ 50 ₽, всего на 21 000 ₽; запущены 11 стоявших, включая тестовую X2 41722971. <a href="/api/wb-bids/reports/wb-budget-topup-low50-2026-11-09">Итог пополнения и запуска</a>. Ниже сохранён более ранний срез.</p>'
body += '<p><b>Обновление после этого среза:</b> владелец отложил чистку и снижение ставок до месячного наблюдения. Создана одна выключенная тестовая РК на 50 X2 с бюджетом 0 ₽; её товары продолжают быть вне работающей рекламы. Таблицы ниже — исходный срез до теста. <a href="/api/wb-bids/reports/wb-acc1-capacity-probe-2026-11-09">Результаты теста 50/200/300 и актуальный следующий шаг</a>.</p>'
body += '<p><b>На 9 ноября: 15 035 неархивных товаров с положительным официальным остатком. В работающих РК — 9 419, вне работающих — 5 616.</b> Из последних 797 уже находятся в приостановленных РК; 4 819 не входят ни в работающие, ни в приостановленные РК.</p>'
body += '<p>Проверены полный текущий состав 86 работающих и 7 приостановленных кампаний. Все 93 — CPC с ручными ставками. Состав взят из API кампаний, не восстановлен по строкам статистики. Статус «работает» не гарантирует показ каждого товара.</p>'
body += '<p>Весь неархивный каталог, включая нулевой остаток: 22 379 карточек; 13 010 входят в работающие РК, 9 369 — вне работающих. Ещё 79 nmID из составов РК отсутствуют в текущем активном каталоге и в таблицу наличия не включены.</p>'
body += table(['Непересекающаяся группа', 'Всего в наличии', 'Работающая реклама', 'Только пауза', 'Нет в незавершённых РК'], group_rows)
body += '<p>Все 4 372 бандла в наличии сейчас вне работающей и приостановленной рекламы: <b>X2 — 1 882; X6 — 1 420; X10 — 1 070</b>. Новинки вне работающей рекламы — 199, дочерние — 429, старые — 616; эти числа включают паузу, поэтому не смешивайте их с последней колонкой.</p>'
body += '<p>Правило разделения: сначала подтверждённые бандлы, затем дочерние (после первых четырёх цифр артикула продолжается числовой номер), затем остальные по возрасту. Новинки — createdAt WB с 09.05.2026 по дату среза; это дата создания карточки, не доказанная дата первой публикации. Дочерние и бандлы повторно в новинки не попадают. Наличие родителей/родственников не является фильтром допуска.</p>'
body += '<h2>Где есть смысл проверить снижение ставок</h2>'
body += f'<p>За 12.10–08.11, 28 полных дней: отчётный расход <b>{money(spend)} ₽</b>, приписанная рекламе стоимость заказов {money(revenue)} ₽, {ad_orders} рекламных заказов по WB, ДРР <b>{money(spend / revenue * 100)}%</b>. Это не доказательство добавочных продаж от рекламы. Самые расходные SKU с расходом 659–722 ₽ имеют ДРР 2,35–3,98%; их не ставлю первыми на снижение только из-за абсолютного расхода.</p>'
body += '<p><b>Два основных кандидата на пробное −10%:</b> расход без приписанных рекламных заказов, минимум 20 кликов, от 250 ₽ за 28 дней и расход сохраняется последнюю неделю. Это предложение для измерения, ставки не менялись.</p>'
head = ['Наш артикул / nmID', 'Расход 28 дн., ₽', 'Клики', 'Заказы рекламы', 'Все заказы SKU', 'Известная склейка: все заказы', 'Ставка сейчас → тест, ₽', 'Мин. WB, ₽']
def plan_row(r):
    return [r['vendor_code'] + ' / ' + r['nm_id'], money(r['spend_28d']), r['clicks_28d'], r['ad_orders_28d'], r['general_orders_28d'],
            r['known_native_model_orders_28d'], r['current_bid_rub'] + ' → ' + r['proposed_bid_rub'], r['native_min_rub']]
body += table(head, [plan_row(r) for r in plans if r['priority'] == 'FIRST_TRIAL'])
body += '<p>239329 — дочерняя карточка, 4209 — основная. Минимум 7,30 ₽ проверен индивидуально чтением API, текущие ставки и присутствие в работающей РК перечитаны отдельно. Цена общего заказа — priceWithDisc WB, не финансовая реализация; общие заказы исключают отменённые строки, а рекламные заказы и суммы взяты как их сообщает WB, без собственного пересчёта отмен. Рекламные заказы могут относиться к ассоциированным конверсиям, поэтому «общие минус рекламные = органика» здесь не рассчитывается.</p>'
body += '<h2>Ещё пять для осторожного разбора</h2>'
body += table(head, [plan_row(r) for r in plans if r['priority'] != 'FIRST_TRIAL'])
body += '<p>У 5421 своих заказов нет, но по фактической склейке есть 12; у 4433 — 2 собственных и 7 по склейке. Их нельзя объявлять пожирателями по одному SKU. У 08517 мало кликов, при этом артикульная семья дала 19 общих заказов. У 5484 всего 15 кликов за 28 дней и небольшой недавний расход; у 0234 один рекламный заказ — оценка ДРР неустойчива. Живой маржи в перенесённой маркетинговой таблице нет, порог окупаемости не выдумывался.</p>'
body += '<p>У 12 других проверенных позиций из расходного пула ставка уже равна индивидуальному минимуму 7,30 ₽. Их общий расход за 28 дней — 2 044 ₽. Дальнейшее снижение ставки для них не предлагается; вопрос паузы — отдельное решение, ничего не выключалось.</p>'
tail = s['paid_no_own_or_ad_orders']
body += f'<h2>Длинный хвост: отдельная задача, не список для автоматической остановки</h2><p>В наличии и работающих РК есть {tail["cards"]} карточки с положительным расходом, но без рекламных и собственных общих заказов за 28 дней. Их расход — {money(tail["spend_28d"])} ₽. У {tail["without_known_native_or_article_orders_cards"]} из них нет заказов также по известной текущей склейке и артикульной семье; расход — {money(tail["without_known_native_or_article_orders_spend_28d"])} ₽.</p>'
body += '<p>Это наблюдаемый пул для следующего исследования: нужны проверка срока наличия, сезона, возраста карточки и отдельный тест паузы. 28 дней без заказов не доказывают отсутствие спроса за год или бесполезность рекламы. Полного годового анализа здесь нет, автоматической паузы нет. По 3 проданным SKU, отсутствующим в текущем неархивном каталоге, артикульная семья восстановлена из supplierArticle заказа; исторический imtID неизвестен. Нулевые модельные заказы означают отсутствие в наблюдаемой карте, а не доказательство всей исторической карты WB.</p>'
body += '<h2>Как измерять пробное снижение</h2><p>Если владелец выберет пилот: отдельный −10% по каждому выбранному nmID и размещению, 7–14 дней с одинаковыми днями недели. Сопоставлять расход, показы, клики, общие заказы и стоимость самого SKU, фактической imtID-склейки и всего WB акк1. Семья по четырём цифрам — отдельный дополнительный уровень, не склейка. Данные рекламы и отмены заказов перечитывать с перекрытием; экономию не предсказывать линейно из ставки. Снижать ставки без команды нельзя.</p>'
body += '<p>В соседнем потоке на 09.11 23:59 МСК подготовлено изменение цен для акции WB 11.11. Перед любым тестом ставок нужно зафиксировать фактический результат этой ценовой операции: изменение цены одновременно со ставкой мешает оценивать эффект.</p>'
body += '<h2>Источники и ограничения</h2><ul><li>Content API: все 22 379 карточек вне корзины, включая createdAt и imtID. Классификация не использует updatedAt как дату новизны.</li><li>Официальный FBS: 30 913 запрошенных баркодов, 30 672 ответа; отсутствующие ответы не считаются нулём. FBO: полный warehouse_remains, исключены транзитные псевдосклады и 373 единицы по действующему учёту потерь/повреждённых складов. 160 карточек с неподтверждённым остатком не включены в наличие.</li><li>Публичный card.wb.ru вернул 403. Поэтому подтверждён официальный остаток, но не покупаемость в конкретном регионе витрины.</li><li>Реклама: 93 текущие РК запрошены, 92 вернули статистику; у 36880283 отдельный повтор вернул null, в журнале затрат записей по ней также нет. Пропуск не подменён нулём. Сумма кампаний и nmID совпала до копейки.</li></ul>'
if charges is not None:
    body += f'<p>Независимый журнал затрат WB /adv/v1/upd: {money(charges)} ₽, источник оплаты в строках «Баланс». Разница со статистикой {money(spend - charges)} ₽ сохранена, не распределена между SKU. Это разные источники, суммы не подгонялись.</p>'
body += '<p>Метод минимальных ставок и единицы копеек: <a href="https://dev.wildberries.kg/docs/openapi/promotion#tag/Sozdanie-kampanij">официальная документация WB API</a>. Все обращения — чтение; POST использован только для чтения карточек, остатков и минимальных ставок. Никакие кампании, бюджеты, цены, ставки, карточки или производственная БД не менялись.</p>'
slug = '/api/wb-bids/reports/wb-acc1-ad-audit-2026-11-09'
body += f'<h2>Полные списки</h2><p><a href="{slug}-outside">5 616 вне работающей рекламы CSV</a> · <a href="{slug}-none">4 819 без работающих/приостановленных РК CSV</a> · <a href="{slug}-bundles">Бандлы CSV</a> · <a href="{slug}-children">Дочерние вне работающей рекламы CSV</a> · <a href="{slug}-new">Новинки вне работающей рекламы CSV</a> · <a href="{slug}-old">Старые вне работающей рекламы CSV</a> · <a href="{slug}-candidates">7 кандидатов и ставки CSV</a> · <a href="{slug}-floor">12 уже на минимуме CSV</a> · <a href="{slug}-tail">Наблюдаемый хвост без собственных/рекламных заказов CSV</a>.</p>'
(P / 'index.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WB акк1: реклама, ассортимент и ставки</title><style>body{font:16px/1.55 system-ui;max-width:1250px;margin:24px auto;padding:0 16px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;border:1px solid #ddd;text-align:left}th{background:#edf2fa}.scroll{overflow-x:auto}a{color:#155ab6}li{margin:8px 0}</style>' + body + '</html>')
(P / 'RESULT.md').write_text('# WB акк1: инвентарь рекламы и кандидаты\n\n' + json.dumps(s, ensure_ascii=False, indent=2) + '\n\nhttps://bi.beyindi.com' + slug + '\n')
